import{_ as t,o as e,c as s,a3 as n}from"./chunks/framework.B9qR_F1m.js";const p=JSON.parse('{"title":"数学","description":"微积分、线性代数与概率统计的学习笔记，全站支持 LaTeX 公式渲染。","frontmatter":{"title":"数学","subject":"math","subjectLabel":"数学","description":"微积分、线性代数与概率统计的学习笔记，全站支持 LaTeX 公式渲染。"},"headers":[],"relativePath":"subjects/math/index.md","filePath":"subjects/math/index.md","lastUpdated":null}'),l={name:"subjects/math/index.md"};function i(r,a,o,c,h,m){return e(),s("div",null,[...a[0]||(a[0]=[n('<h1 id="数学" tabindex="-1">数学 <a class="header-anchor" href="#数学" aria-label="Permalink to &quot;数学&quot;">​</a></h1><p>这里收录数学方向的学习笔记，按 <strong>微积分 / 线性代数 / 概率统计</strong> 三条线组织。所有页面支持 LaTeX： 行内公式写 <code>$ f&#39;(x) $</code>，独立公式用 <code>$$ ... $$</code> 换行包围。</p><h2 id="分类导航" tabindex="-1">分类导航 <a class="header-anchor" href="#分类导航" aria-label="Permalink to &quot;分类导航&quot;">​</a></h2><h3 id="微积分" tabindex="-1">微积分 <a class="header-anchor" href="#微积分" aria-label="Permalink to &quot;微积分&quot;">​</a></h3><ul><li><a href="./calculus/limits-and-continuity">极限与连续（写作模板）</a> —— 从 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>ε</mi></mrow><annotation encoding="application/x-tex">\\varepsilon</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.4306em;"></span><span class="mord mathnormal">ε</span></span></span></span>-<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>δ</mi></mrow><annotation encoding="application/x-tex">\\delta</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0379em;">δ</span></span></span></span> 语言到连续性判定</li><li><a href="./calculus/derivatives">导数与微分应用</a> —— 求导法则、极值与最值、凹凸性</li></ul><h3 id="线性代数" tabindex="-1">线性代数 <a class="header-anchor" href="#线性代数" aria-label="Permalink to &quot;线性代数&quot;">​</a></h3><ul><li><a href="./linear-algebra/matrices">矩阵与行列式</a> —— 运算规则、秩、可逆条件</li></ul><h3 id="概率统计" tabindex="-1">概率统计 <a class="header-anchor" href="#概率统计" aria-label="Permalink to &quot;概率统计&quot;">​</a></h3><ul><li><a href="./probability/random-variables">随机变量与分布</a> —— 分布函数、常见离散与连续分布</li></ul><h2 id="学习路径建议" tabindex="-1">学习路径建议 <a class="header-anchor" href="#学习路径建议" aria-label="Permalink to &quot;学习路径建议&quot;">​</a></h2><ol><li>先把<strong>极限</strong>的定义和语言读熟，它是后面所有概念的地基；</li><li>再进入<strong>导数与积分</strong>，重点体会「局部线性化」和「累积量」这两种视角；</li><li>线性代数与微积分并行推进，遇到多元函数时两者会合流；</li><li>概率统计放在最后，它需要积分作为工具。</li></ol><blockquote><p><strong>提示</strong>：公式写错时页面不会白屏，KaTeX 会把出错的公式标红显示，命令行也会给出警告。</p></blockquote>',12)])])}const u=t(l,[["render",i]]);export{p as __pageData,u as default};
